params.definition:
{
  "kind": "parametric-object",
  "meta": {
    "name": "Staircase",
    "units": "m"
  },
  "parameters": [
    {
      "key": "config",
      "label": "Configuration",
      "kind": "select",
      "default": "straight",
      "options": [
        {
          "value": "straight",
          "label": "Straight"
        },
        {
          "value": "u-shape",
          "label": "U-shape (180°)"
        },
        {
          "value": "u-shape-mid",
          "label": "U-shape + mid"
        }
      ]
    },
    {
      "key": "steps",
      "label": "Steps",
      "kind": "number",
      "default": 14,
      "min": 2,
      "max": 60,
      "step": 1
    },
    {
      "key": "tread",
      "label": "Tread (going)",
      "kind": "number",
      "default": 0.28,
      "min": 0.2,
      "max": 0.45,
      "step": 0.005
    },
    {
      "key": "riser",
      "label": "Riser",
      "kind": "number",
      "default": 0.17,
      "min": 0.1,
      "max": 0.25,
      "step": 0.005
    },
    {
      "key": "width",
      "label": "Width",
      "kind": "number",
      "default": 1,
      "min": 0.6,
      "max": 3,
      "step": 0.05
    },
    {
      "key": "direction",
      "label": "Direction",
      "kind": "select",
      "default": "ltr",
      "options": [
        {
          "value": "ltr",
          "label": "Left → Right"
        },
        {
          "value": "rtl",
          "label": "Right → Left"
        }
      ]
    },
    {
      "key": "midSteps",
      "label": "Mid / split steps",
      "kind": "number",
      "default": 0,
      "min": 0,
      "max": 40,
      "step": 1
    },
    {
      "key": "landingWidth",
      "label": "Landing depth",
      "kind": "number",
      "default": 1,
      "min": 0.5,
      "max": 3,
      "step": 0.05
    },
    {
      "key": "midSpace",
      "label": "Mid space",
      "kind": "number",
      "default": 0.1,
      "min": 0,
      "max": 1,
      "step": 0.05
    },
    {
      "key": "rotation",
      "label": "Rotation",
      "kind": "number",
      "default": 0,
      "min": 0,
      "max": 360,
      "step": 1
    },
    {
      "key": "color",
      "label": "Colour",
      "kind": "color",
      "default": "#0f766e"
    }
  ],
  "geometry": {
    "emit": "boxes",
    "vars": {
      "N": "max(2, round(steps))",
      "T": "max(0.05, tread)",
      "W": "max(0.1, width)",
      "L": "max(0, landingWidth)",
      "G": "max(0, midSpace)",
      "R": "max(0.05, riser)",
      "MS": "round(midSteps)",
      "dir": "direction == 'rtl' ? -1 : 1"
    },
    "cases": [
      {
        "when": "config == 'straight'",
        "rules": [
          {
            "repeat": "N",
            "as": "i",
            "box": {
              "x0": "dir*i*T",
              "x1": "dir*(i+1)*T",
              "y0": "0",
              "y1": "W",
              "h0": "0",
              "h1": "(i+1)*R"
            }
          },
          {
            "when": "L > 0",
            "box": {
              "x0": "dir*N*T",
              "x1": "dir*(N*T + L)",
              "y0": "0",
              "y1": "W",
              "h0": "0",
              "h1": "N*R"
            }
          }
        ]
      },
      {
        "when": "config == 'u-shape'",
        "vars": {
          "n1": "(MS > 0 && MS < N) ? MS : floor(N/2)",
          "n2": "N - n1",
          "xt": "dir*n1*T",
          "xl": "xt + dir*L"
        },
        "rules": [
          {
            "repeat": "n1",
            "as": "i",
            "box": {
              "x0": "dir*i*T",
              "x1": "dir*(i+1)*T",
              "y0": "0",
              "y1": "W",
              "h0": "0",
              "h1": "(i+1)*R"
            }
          },
          {
            "box": {
              "x0": "xt",
              "x1": "xl",
              "y0": "0",
              "y1": "2*W + G",
              "h0": "0",
              "h1": "n1*R"
            }
          },
          {
            "repeat": "n2",
            "as": "j",
            "box": {
              "x0": "xt - dir*j*T",
              "x1": "xt - dir*(j+1)*T",
              "y0": "W + G",
              "y1": "2*W + G",
              "h0": "0",
              "h1": "(n1 + j + 1)*R"
            }
          }
        ]
      },
      {
        "when": "config == 'u-shape-mid'",
        "vars": {
          "mid": "(MS > 0 && MS < N - 1) ? MS : max(1, round(N/3))",
          "rem": "max(2, N - mid)",
          "a": "ceil(rem/2)",
          "b": "rem - a",
          "xt": "dir*a*T",
          "xr": "xt + dir*W",
          "y2": "W + mid*T",
          "y3": "y2 + W"
        },
        "rules": [
          {
            "repeat": "a",
            "as": "i",
            "box": {
              "x0": "dir*i*T",
              "x1": "dir*(i+1)*T",
              "y0": "0",
              "y1": "W",
              "h0": "0",
              "h1": "(i+1)*R"
            }
          },
          {
            "box": {
              "x0": "xt",
              "x1": "xr",
              "y0": "0",
              "y1": "W",
              "h0": "0",
              "h1": "a*R"
            }
          },
          {
            "repeat": "mid",
            "as": "k",
            "box": {
              "x0": "xt",
              "x1": "xr",
              "y0": "W + k*T",
              "y1": "W + (k+1)*T",
              "h0": "0",
              "h1": "(a + k + 1)*R"
            }
          },
          {
            "box": {
              "x0": "xt",
              "x1": "xr",
              "y0": "y2",
              "y1": "y3",
              "h0": "0",
              "h1": "(a + mid)*R"
            }
          },
          {
            "repeat": "b",
            "as": "j",
            "box": {
              "x0": "xt - dir*j*T",
              "x1": "xt - dir*(j+1)*T",
              "y0": "y2",
              "y1": "y3",
              "h0": "0",
              "h1": "(a + mid + j + 1)*R"
            }
          }
        ]
      }
    ]
  }
}
